    gi=G[ki]; go=G[ko]
    cs=comps_diag(gi)
    grp={}
    for c,cells in cs: p,r0,c0=norm(cells); grp.setdefault(p,[]).append((c,(r0,c0),cells))
    print(ki,'groups:',[(p,len(v)) for v in grp.values()])
    got=[list(r) for r in gi]
