                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,tuple(sorted(cells))))
    return out
def shape_cells(cells):
    ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
def f(g):
    cs=comps_orth(g)
    patmap={}
    for c,cells in cs:
        s=shape_cells(cells); patmap.setdefault(s,[]).append((c,tuple(sorted(cells))))
    go=[row[:] for row in g]
    for s,lis in patmap.items():
        if len(lis)<2: continue
        # only color-1 comps change to the other's color in demos; but test may differ - use majority vote per group over non-self colors
        targets=Counter(c for c,_ in lis if c!=1)
        if not targets: continue
        for c,cellset in lis:
            if c==1:
                for y,x in cellset: go[y][x]=targets.most_common(1)[0][0]
    return go
for n in ['1','2','3']:
    gi=G[f'Demo pair {n} input']
    ok=f(gi)==G[f'Demo pair {n} output']
    print(n,ok)
print(json.dumps(f(G['Test input'])))
